import { useMutation,useQuery,useQueryClient } from '@tanstack/react-query';
import { useState } from 'react'; import { qk } from '../api/keys.js'; import { useClient } from '../hooks/useClient.js';
export function SituationPage(){const client=useClient();const qc=useQueryClient();const [focus,setFocus]=useState('');const query=useQuery({queryKey:client?qk.situation(client.config):['situation','none'],enabled:!!client,queryFn:async()=> (await client.situation()).value});const mutation=useMutation({mutationFn:(v)=>client.setFocus(v),onSuccess:()=>qc.invalidateQueries({queryKey:qk.situation(client.config)})});if(!client)return <p>Connect to the BFF first.</p>;return <section><h2>Situation</h2>{query.isLoading&&<p>Loading…</p>}{query.error&&<pre className="error">{query.error.message}</pre>}{query.data&&<pre>{JSON.stringify(query.data,null,2)}</pre>}<form onSubmit={(e)=>{e.preventDefault();if(focus.trim())mutation.mutate(focus.trim());}}><label>Focus<input value={focus} onChange={e=>setFocus(e.target.value)}/></label><button>Update focus</button></form></section>}
