import { useQuery } from '@tanstack/react-query'; import { useClient } from './useClient.js'; import { useUiStore } from '../stores/ui.js'; export function useDashboard(){const client=useClient();const analysis=useUiStore(s=>s.analysis);const operation=useUiStore(s=>s.operation);return useQuery({queryKey:['dashboard',analysis,operation],enabled:!!client&&!!analysis,queryFn:async()=> (await client.dashboard(analysis,operation)).value});}
