import { useQueries } from '@tanstack/react-query'; import { useDashboard } from '../hooks/useDashboard.js'; import { useClient } from '../hooks/useClient.js'; import { useUiStore } from '../stores/ui.js';
export function InspectorPage(){const client=useClient();const dashboard=useDashboard();const analysis=useUiStore(s=>s.analysis);const specs=[['review',()=>client.analysisReview(analysis)],['coverage',()=>client.analysisCoverage(analysis)],['context',()=>client.analysisContext(analysis)],['delta',()=>client.analysisDelta(analysis)]];const qs=useQueries({queries:specs.map(([name,fn])=>({queryKey:['inspector',analysis,name],enabled:!!client&&!!analysis,queryFn:async()=> (await fn()).value}))});return <section><h2>Dense inspector</h2><div className="mobile-fallback">This dense inspection surface is desktop-only in V1.0.0.0.0.0.</div><div className="desktop-only"><article><h3>BFF dashboard</h3><pre>{JSON.stringify(dashboard.data??null,null,2)}</pre></article></div><div className="desktop-only inspector-grid">{specs.map(([name],i)=><article key={name}><h3>{name}</h3><pre>{JSON.stringify(qs[i].data??null,null,2)}</pre></article>)}</div></section>}
