import { useForm } from 'react-hook-form'; import { zodResolver } from '@hookform/resolvers/zod'; import { analysisSchema } from '../config.js'; import { useUiStore } from '../stores/ui.js';
export function AnalysisPage(){const analysis=useUiStore(s=>s.analysis);const setAnalysis=useUiStore(s=>s.setAnalysis);const {register,handleSubmit}=useForm({resolver:zodResolver(analysisSchema),defaultValues:{analysis}});return <section><h2>Analysis</h2><form onSubmit={handleSubmit(v=>setAnalysis(v.analysis))}><input aria-label="Analysis UUID" placeholder="Analysis UUID" {...register('analysis')}/><button>Select analysis</button></form><p>Selected: <code>{analysis||'none'}</code></p><p>The reasoning controller, claims, assumptions, alternatives, evidence gaps, decisions and human gates remain server-owned; this route chooses which analysis the UI inspects.</p></section>}
